def min_replacements_to_lucky(ticket):
    first_three_sum = sum(int(digit) for digit in ticket[:3])
    last_three_sum = sum(int(digit) for digit in ticket[3:])

    if first_three_sum == last_three_sum:
        return 0

    min_replacements = float('inf')

    for i in range(3):
        for j in range(i + 1, 3):
            for k in range(j + 1, 3):
                for l in range(3):
                    for m in range(l + 1, 3):
                        for n in range(m + 1, 3):
                            new_ticket = list(ticket)
                            new_ticket[i] = str((first_three_sum - last_three_sum) // 3)
                            new_ticket[j] = str((first_three_sum - last_three_sum) // 3)
                            new_ticket[k] = str((first_three_sum - last_three_sum) % 3)
                            new_ticket[l] = str((last_three_sum - first_three_sum) // 3)
                            new_ticket[m] = str((last_three_sum - first_three_sum) // 3)
                            new_ticket[n] = str((last_three_sum - first_three_sum) % 3)
                            if sum(int(digit) for digit in new_ticket[:3]) == sum(int(digit) for digit in new_ticket[3:]):
                                min_replacements = min(min_replacements, 6 - len(set(new_ticket)))

    return min_replacements

